import { TopicItem } from '../types';

type Lesson = Pick<TopicItem, 'summary' | 'lessonSections' | 'example' | 'references' | 'quickQuestions'>;

const q = (id: string, prompt: string, correctAnswer: 'certo' | 'errado', explanation: string) => ({
  id, prompt, source: 'Questão autoral para treino', correctAnswer, explanation,
});

export const PORTUGUES_BLOCO1_CONTENT: Record<string, Lesson> = {
  'portugues-3': {
    summary: 'Compreender um texto é localizar e relacionar informações expressas; interpretar é construir inferências justificadas por pistas textuais e contexto. Em questões, a resposta precisa respeitar o que o texto afirma, pressupõe ou permite concluir, sem acrescentar informação externa como se estivesse escrita.',
    lessonSections: [
      { heading: '1. Compreensão e interpretação', body: `Compreensão não é apenas copiar uma frase: envolve localizar informações, reconhecer paráfrases, identificar referentes, estabelecer relações entre partes e entender o sentido de palavras no contexto. A informação pode estar explícita em diferentes trechos e exigir combinação de dados.\n\nInterpretação envolve inferir ideias implícitas, propósito, ponto de vista, ironia, pressupostos e consequências. A inferência válida não é um palpite livre: deve ser sustentada por elementos do texto. Distinguir fato textual, inferência autorizada e conhecimento de mundo evita extrapolações.` },
      { heading: '2. Como resolver questões', body: `Leia o comando com atenção: “segundo o texto” costuma exigir apoio direto; “infere-se” pede uma conclusão sustentada; “a finalidade” pergunta o propósito comunicativo; “o termo retoma” pede identificar referente. Volte ao trecho relevante, confira conectivos, negações, quantificadores e restrições como “alguns”, “apenas” e “nem todos”.\n\nElimine alternativas que contradigam o texto, generalizem um caso particular, troquem possibilidade por certeza, invertam causa e consequência ou introduzam dado não apresentado. Uma alternativa pode usar palavras diferentes do texto e ainda ser correta se preservar o sentido; uma cópia literal pode ser inadequada se ignorar o comando ou o contexto.` },
      { heading: '3. Gênero, propósito e ponto de vista', body: `O gênero e a situação comunicativa ajudam a interpretar, mas não determinam sozinhos a resposta. Um texto informativo pode conter avaliação; uma crônica pode combinar observação e ironia; um artigo opinativo pode apresentar dados e argumentos. Identifique quem enuncia, a quem se dirige, sobre o que fala e com que finalidade.\n\nNão classifique automaticamente textos científicos como “só compreensão” nem literários como “livres para qualquer interpretação”. Mesmo em textos literários, a leitura proposta deve se apoiar em escolhas lexicais, imagens, estrutura, voz e contexto fornecidos.` },
      { heading: '4. Exemplo resolvido e treino', body: `Texto: “O velho sentou-se no banco da praça. Observou os pássaros por um longo tempo. Depois, suspirou fundo e fechou os olhos. O sol da tarde aquecia seu rosto.” Pergunta: o que fez depois de observar os pássaros? Resposta: suspirou e fechou os olhos — informação explícita.\n\nPergunta: qual estado emocional pode ser sugerido? A cena pode sugerir descanso, reflexão ou melancolia, mas não permite afirmar com certeza que ele estava triste ou feliz. A expressão “pode sugerir” é mais adequada do que tratar uma inferência aberta como fato.` },
    ],
    example: 'Para avaliar “O velho estava triste”, pergunte: o texto declara tristeza? Não. Há pistas compatíveis com reflexão ou melancolia, mas também com descanso. A conclusão categórica extrapola; “a cena pode sugerir melancolia” é uma inferência possível, não a única.',
    references: [],
    quickQuestions: [q('portugues-3-q1', 'Uma inferência pode ir além das palavras explícitas, desde que seja sustentada por pistas do texto.', 'certo', 'Interpretar exige deduzir, mas a conclusão precisa ser compatível com elementos textuais e não pode inventar fatos.')],
  },
  'portugues-4': {
    summary: 'O contexto histórico, social e cultural participa da produção e da recepção de um texto. Ele ajuda a explicar referências, valores, conflitos e escolhas de linguagem, mas não autoriza atribuir ao texto qualquer sentido sem evidência textual.',
    lessonSections: [
      { heading: '1. Texto, época e situação de produção', body: `Um texto é produzido por alguém, em determinada situação, para interlocutores e objetivos específicos. O contexto pode incluir período histórico, instituições, debates, condições sociais, público, suporte e circulação. Esses elementos ajudam a entender por que certos temas e formas de expressão aparecem.\n\nConsidere separadamente autor empírico, voz que fala no texto e personagem. Em poesia e ficção, o eu lírico ou narrador não deve ser automaticamente identificado com o autor. Em textos argumentativos, a tese pode ser atribuída ao enunciador textual, mas ainda deve ser demonstrada pelas marcas do discurso.` },
      { heading: '2. Contexto como pista, não como substituto', body: `Conhecer o contexto esclarece referências e ironias, mas a leitura deve combinar informação contextual e evidência interna. Não basta saber a data para concluir a intenção do autor. Procure vocabulário, imagens, argumentos, pressupostos e relações com acontecimentos ou ideias do período.\n\nUma frase como “ordem e progresso” pode funcionar de modos diferentes conforme o gênero, a situação e o tom. A mesma formulação pode ser lema, citação, elogio ou ironia. O contexto restringe interpretações plausíveis; não transforma uma hipótese em certeza sem sinais no texto.` },
      { heading: '3. Perguntas úteis para a prova', body: `Pergunte: quando e onde circula o texto? Quem é o enunciador e quem é o destinatário? Qual problema ou debate está em jogo? Que valores são defendidos ou criticados? O texto informa, persuade, satiriza, registra ou instrui? O que no próprio texto sustenta essa leitura?\n\nSe o enunciado fornecer uma nota histórica, use-a como dado do problema. Se não fornecer, não invente biografia, intenção política ou contexto específico que não possa ser confirmado pelas pistas apresentadas.` },
      { heading: '4. Exemplo comparativo', body: `Compare duas afirmações sobre a participação feminina no trabalho: uma que defenda papéis domésticos rígidos e outra que destaque a busca por igualdade. Diferenças históricas podem explicar os valores pressupostos em cada formulação, mas a análise deve apontar as palavras e argumentos que revelam esses valores.\n\nEm uma questão, “o contexto histórico contribui para compreender a visão de mundo representada” pode ser adequado. “A data, por si só, prova que o autor pretendia defender determinada política” é uma conclusão excessiva.` },
    ],
    example: 'Se uma crônica antiga apresenta uma personagem limitada por normas sociais, use o contexto para compreender essas normas; depois localize no texto as ações, descrições e comentários que mostram se o narrador as naturaliza ou critica.',
    references: [],
    quickQuestions: [q('portugues-4-q1', 'A época de publicação, isoladamente, prova a intenção do autor e determina uma única interpretação possível.', 'errado', 'O contexto auxilia a leitura, mas precisa ser articulado com marcas textuais e não comprova sozinho uma intenção específica.')],
  },
  'portugues-5': {
    summary: 'Denotação é o uso de uma expressão em sentido literal ou convencionalmente direto; conotação é o uso associado, figurado ou expressivo construído no contexto. A classificação depende da frase, do gênero e do efeito de sentido, não de uma lista fixa de palavras.',
    lessonSections: [
      { heading: '1. Sentido literal e sentido figurado', body: `Em uso denotativo, “coração” pode nomear o órgão; em uso conotativo, pode representar sentimentos. “A sala estava fria” pode informar temperatura baixa ou, em certo contexto, sugerir acolhimento emocional ausente. A palavra não é conotativa por natureza: é o uso contextual que importa.\n\nTextos técnicos tendem a privilegiar precisão denotativa, enquanto textos literários e publicitários podem explorar imagens e associações. Isso é tendência, não regra absoluta: textos informativos também usam metáforas, e textos literários podem incluir descrições literais.` },
      { heading: '2. Como identificar o efeito', body: `Leia a frase e o trecho ao redor. Pergunte se a expressão descreve uma situação concreta ou se desloca o significado para produzir imagem, avaliação, humor ou intensidade. Testar uma paráfrase literal pode ajudar, mas a substituição precisa preservar o contexto.\n\nNão confunda conotação com falsidade ou metáfora. Uma expressão figurada pode comunicar uma ideia com precisão no gênero em que aparece. Também não basta uma palavra parecer “poética”: verifique qual sentido ela assume naquela ocorrência.` },
      { heading: '3. Pares contrastivos', body: `“O leão saiu da jaula” usa “leão” no sentido literal; “O capitão foi um leão na defesa” usa o animal como imagem de coragem ou força. “A resposta veio fria” pode descrever temperatura em contexto físico ou distanciamento afetivo em um diálogo.\n\nMetonímias e expressões convencionais também podem envolver deslocamento de sentido: “Li Machado de Assis” normalmente significa que li uma obra do autor. Em uma prova, explique o sentido produzido pelo contexto, em vez de apenas rotular a palavra isolada.` },
      { heading: '4. Questão resolvida', body: `Em “A pesquisadora percorreu um caminho de ideias”, “caminho” provavelmente não designa uma via física; representa o percurso intelectual. O contexto constrói sentido figurado. Já em “A equipe percorreu o caminho até o laboratório”, o referente pode ser uma rota real.\n\nDica: D de denotação lembra definição direta; C de conotação pode lembrar contexto e criação de associação. O macete auxilia a memória, mas a frase continua sendo a prova decisiva.` },
    ],
    example: '“A casa pegou fogo” descreve um incêndio literal; “A discussão pegou fogo” usa a expressão para indicar que a discussão se intensificou. A forma verbal é a mesma, mas o contexto altera o sentido.',
    references: [],
    quickQuestions: [q('portugues-5-q1', 'Uma palavra tem sempre sentido conotativo ou denotativo independentemente da frase em que aparece.', 'errado', 'A mesma palavra pode ser usada literalmente ou em sentido figurado; a classificação depende do contexto.')],
  },
  'portugues-6': {
    summary: 'Discurso direto, indireto e indireto livre são modos de representar falas ou pensamentos. A passagem de um modo a outro pode alterar marcas gráficas, pessoa, dêixis, tempos verbais e organização sintática, mas as mudanças dependem do contexto e do ponto de referência temporal.',
    lessonSections: [
      { heading: '1. Discurso direto', body: `No discurso direto, a fala é apresentada como fala da personagem, geralmente marcada por travessão, aspas ou dois-pontos. O narrador pode introduzi-la com verbo de elocução (dizer, perguntar, responder) ou inseri-la sem esse verbo. A pontuação e a disposição variam conforme o gênero e o estilo editorial.\n\nExemplo: Maria perguntou: “Você vai ao cinema hoje?” A pergunta aparece diretamente, com a forma de tratamento e a dêixis próprias da situação da fala. Discurso direto cria efeito de presença, mas não garante reprodução documental palavra por palavra: continua sendo uma representação construída pelo texto.` },
      { heading: '2. Discurso indireto', body: `No discurso indireto, o narrador integra a fala à sua própria oração: “Maria perguntou se João iria ao cinema naquele dia”. Perguntas totais costumam ser introduzidas por “se”; perguntas parciais preservam o interrogativo: “Perguntou onde ele morava”. Ordens e pedidos podem ser expressos por infinitivo ou oração com subjuntivo: “Mandou-o sair” / “Pediu que ele saísse”.\n\nAo transpor, ajuste pronomes e expressões de lugar ou tempo apenas quando o novo ponto de enunciação exigir. “Hoje” pode virar “naquele dia” se o relato ocorrer em outro momento; pode permanecer “hoje” se o narrador ainda estiver no mesmo dia e a referência continuar válida.` },
      { heading: '3. Correlação verbal na transposição', body: `Em relatos retrospectivos, é comum haver recuo temporal: presente → imperfeito (“estou” → “estava”), futuro do presente → futuro do pretérito (“viajarei” → “viajaria”), e pretérito perfeito → mais-que-perfeito composto (“viajei” → “tinha viajado”). Essas correspondências são frequentes, mas não mecânicas nem obrigatórias em toda situação.\n\nSe o fato continua verdadeiro ou o narrador mantém o mesmo marco temporal, o presente pode ser preservado: “O pesquisador afirmou que a água ferve a 100 °C” (a verdade geral continua válida). A questão normalmente fornece contexto suficiente para avaliar se a reescrita preserva tempo, pessoa, modalidade e sentido.` },
      { heading: '4. Discurso indireto livre', body: `No discurso indireto livre, traços da fala ou do pensamento da personagem aparecem misturados à narração, sem uma oração introdutória explícita nem necessariamente aspas ou travessão. Pode haver marcas de avaliação, interrogação, exclamação e vocabulário próprios da personagem, enquanto a narrativa mantém a terceira pessoa.\n\nExemplo: “João caminhava pela rua. Será que ela viria? Já esperava havia uma hora. Que absurdo!” O leitor percebe a perspectiva de João sem a fórmula “João pensou que”. A identificação depende do contexto; a ausência de verbo de dizer, sozinha, não basta para classificar qualquer frase como indireto livre.` },
      { heading: '5. Comparação e resolução de questão', body: `Direto: “Ana disse: ‘Estou cansada’.” Indireto: “Ana disse que estava cansada.” Indireto livre: “Ana sentou-se. Estava cansada; não aguentava mais.” No terceiro caso, narração e perspectiva da personagem se aproximam.\n\nAo analisar uma transformação, confira: quem fala; quem é referido; quando e onde a fala ocorreu; se a frase era pergunta, ordem ou afirmação; e se a nova forma preserva a intenção. Não aplique uma tabela de troca de tempos sem determinar o marco temporal.` },
    ],
    example: '“Pedro disse ontem: ‘Voltarei amanhã’.” Em relato posterior, uma forma possível é “Pedro disse que voltaria no dia seguinte”. Se o narrador reproduz a fala no mesmo dia e preserva a referência temporal, a escolha de “amanhã” pode ser mantida. O contexto decide.',
    references: [],
    quickQuestions: [q('portugues-6-q1', 'Na passagem para o discurso indireto, todas as formas verbais e expressões de tempo devem obrigatoriamente recuar uma posição.', 'errado', 'O ajuste depende do momento do relato, da permanência do fato e do ponto de referência; tabelas mostram correspondências frequentes, não uma troca universal.')],
  },
  'portugues-7': {
    summary: 'Intertextualidade é a relação de diálogo, retomada ou transformação entre textos. Figuras de linguagem são recursos que produzem efeitos semânticos, sintáticos ou sonoros. A análise deve mostrar qual pista formal ocorre e que efeito ela cria no contexto.',
    lessonSections: [
      { heading: '1. Intertextualidade: reconhecimento e efeito', body: `Um texto pode citar, aludir, parafrasear, parodiar ou retomar a estrutura de outro. A relação pode ser explícita, com aspas e indicação de autoria, ou implícita, reconhecida por tema, personagem, fórmula, imagem ou construção. A simples coincidência de assunto não prova intertextualidade; procure uma retomada identificável.\n\nCitação reproduz palavras de outro texto; paráfrase reformula preservando a ideia central; paródia transforma uma referência com efeito humorístico, crítico ou contestador; alusão sugere uma referência sem a desenvolver diretamente. A classificação depende do modo de retomada e do efeito, e essas categorias podem se sobrepor.` },
      { heading: '2. Figuras de palavra e de sentido', body: `Metáfora transfere sentido por associação implícita (“aquela ideia é uma semente”); comparação explicita o paralelo (“como uma semente”). Metonímia substitui um termo por outro associado (“li Machado”, isto é, uma obra do autor). Catacrese usa uma denominação figurada já convencional por falta de termo corrente (“pé da mesa”). Sinestesia combina campos sensoriais (“voz áspera”, “cor quente”).\n\nPerífrase substitui um nome por expressão descritiva (“Cidade Luz”); antonomásia é frequentemente tratada como perífrase que identifica pessoa ou entidade por característica (“Poeta dos Escravos”). As classificações variam entre gramáticas; em prova, priorize a relação descrita e as alternativas apresentadas.` },
      { heading: '3. Figuras de pensamento', body: `Antítese aproxima ideias opostas (“dia e noite”); paradoxo reúne termos ou ideias aparentemente incompatíveis, criando tensão de sentido (“silêncio eloquente”). Ironia produz sentido que contrasta com a formulação literal, reconhecível por contexto e tom; não é simplesmente dizer o contrário em todas as situações.\n\nEufemismo atenua uma referência; hipérbole intensifica por exagero; personificação atribui ação ou traço humano a ser não humano; gradação organiza uma sequência em progressão ou regressão. Em questões, nomeie a figura e explique o efeito, sem confundir oposição simples com contradição paradoxal.` },
      { heading: '4. Figuras de construção', body: `Elipse omite termo recuperável pelo contexto; zeugma é um tipo de elipse em que o termo omitido já apareceu: “Eu prefiro café; ela, chá”. Assíndeto coordena sem conectivo expresso; polissíndeto repete conjunções. Anáfora repete palavra ou expressão no início de segmentos sucessivos. Pleonasmo pode ser recurso expressivo (“vi com meus próprios olhos”) ou redundância inadequada, conforme o uso.\n\nA ausência do pronome sujeito em “Fomos ao cinema” é normalmente analisada como sujeito oculto/desinencial em gramáticas escolares, não como exemplo típico de elipse sintática. Para classificar, observe que elemento foi omitido e se a omissão é recuperável ou estilisticamente marcada.` },
      { heading: '5. Figuras sonoras e método de análise', body: `Aliteração repete sons consonantais; assonância repete sons vocálicos; onomatopeia imita ou representa convencionalmente um som. Examine sons efetivamente repetidos, não apenas letras: uma letra pode ter sons distintos e sons parecidos podem ser escritos de formas diferentes.\n\nMétodo: localize a construção; identifique a relação (semelhança, oposição, omissão, repetição ou substituição); descreva o efeito no trecho. Uma figura pode cumprir mais de uma função, e o rótulo sem explicação não demonstra a interpretação.` },
    ],
    example: 'Em “O vento sussurrava segredos”, a ação humana “sussurrar” é atribuída ao vento: personificação. Em “Li Machado de Assis durante as férias”, o nome do autor substitui a obra: metonímia. A análise parte da relação de sentido, não só da palavra em destaque.',
    references: [],
    quickQuestions: [q('portugues-7-q1', 'Uma metáfora apresenta necessariamente a palavra “como” para indicar comparação.', 'errado', 'A metáfora aproxima sentidos implicitamente; a comparação explícita costuma usar “como”, “tal qual” ou construção equivalente.')],
  },
  'portugues-8': {
    summary: 'Morfologia classifica palavras e suas flexões; sintaxe analisa as funções que palavras e grupos exercem na oração. Morfossintaxe combina as duas perspectivas: uma mesma classe pode desempenhar funções diferentes, e uma função pode ser expressa por estruturas de classes distintas.',
    lessonSections: [
      { heading: '1. Classe gramatical não é função sintática', body: `Substantivo, adjetivo, verbo, pronome, artigo, numeral, advérbio, preposição, conjunção e interjeição são classes gramaticais. Sujeito, objeto direto, objeto indireto, predicativo, adjunto adnominal, complemento nominal, adjunto adverbial, aposto e vocativo são funções sintáticas. Não confunda “adjetivo” com “adjunto adnominal”: o primeiro é classe; o segundo, função.\n\nUma palavra pode mudar de classe conforme o emprego. Em “o jantar esfriou”, “jantar” é substantivo; em “vamos jantar”, é verbo. Um mesmo adjetivo pode ser adjunto adnominal em “casa antiga” ou predicativo em “a casa é antiga”.` },
      { heading: '2. Comece pela estrutura da oração', body: `Localize o verbo ou a locução verbal e pergunte quem ou o que se declara. O sujeito pode ser simples, composto, oculto, indeterminado ou inexistente, conforme a construção. O predicado informa algo sobre o sujeito ou apresenta um processo sem sujeito, nos casos de verbos impessoais.\n\nDepois examine os complementos exigidos pelo verbo: objeto direto normalmente sem preposição obrigatória; objeto indireto introduzido por preposição exigida; predicativo atribui estado ou qualidade; adjuntos acrescentam circunstâncias ou determinam nomes. A regência ajuda a distinguir funções, mas a forma isolada não resolve todos os casos.` },
      { heading: '3. Exemplo de análise integrada', body: `Em “O professor velho explicou a matéria”, “professor” é substantivo e núcleo do sujeito; “o” é artigo e “velho” é adjetivo, ambos determinando o substantivo (adjuntos adnominais). “Explicou” é verbo transitivo direto neste contexto; “a matéria” é objeto direto, cujo núcleo é o substantivo “matéria”; “a” é artigo.\n\nEm “O professor explicou a matéria com calma”, “com calma” é expressão preposicionada com função de adjunto adverbial de modo. Em “O professor estava calmo”, “calmo” é adjetivo com função de predicativo do sujeito. A classe não determina sozinha a função.` },
      { heading: '4. Termos que costumam ser confundidos', body: `Adjunto adnominal acompanha um nome para determiná-lo, caracterizá-lo ou quantificá-lo. Complemento nominal completa o sentido de um nome abstrato, adjetivo ou advérbio e vem preposicionado. Em “amor de mãe”, a relação pode ser de agente ou origem; em “amor à mãe”, “à mãe” tende a completar o sentido do nome. O contexto e a relação semântica são decisivos.\n\nPredicativo atribui característica ao sujeito ou ao objeto por meio de verbo de ligação ou verbo significativo. Vocativo chama o interlocutor e não integra a estrutura de sujeito; aposto explica, resume ou especifica outro termo. Pontuação ajuda a reconhecer algumas estruturas, mas não substitui a análise sintática.` },
      { heading: '5. Procedimento para questões', body: `1. Encontre o verbo e delimite a oração. 2. Identifique o sujeito e o predicado. 3. Analise regência e complementos. 4. Localize modificadores de nomes e circunstâncias. 5. Só então classifique a palavra destacada morfologicamente e sua função sintática.\n\nEm “O amor verdadeiro é raro”, “verdadeiro” é adjetivo e, na análise escolar usual, adjunto adnominal de “amor”. Em “O amor é verdadeiro”, continua sendo adjetivo, mas funciona como predicativo do sujeito.` },
    ],
    example: '“Ela comprou um carro novo ontem.” Ela = pronome pessoal, sujeito; comprou = verbo; “um carro novo” = objeto direto; carro = núcleo, um = artigo e novo = adjetivo/adjunto adnominal; ontem = advérbio com função de adjunto adverbial de tempo.',
    references: [],
    quickQuestions: [q('portugues-8-q1', '“Adjetivo” e “adjunto adnominal” nomeiam a mesma categoria gramatical.', 'errado', 'Adjetivo é classe morfológica; adjunto adnominal é função sintática. Um adjetivo pode exercer outras funções, como predicativo.')],
  },
  'portugues-9': {
    summary: 'A estrutura vocabular envolve morfemas, como radical, afixos e desinências. Processos de formação incluem derivação e composição, além de outros mecanismos. A análise deve considerar a história e o funcionamento da palavra, evitando decomposições intuitivas que não correspondem à formação reconhecida.',
    lessonSections: [
      { heading: '1. Morfemas e estrutura', body: `Radical é a base lexical que concentra o núcleo de significado e pode apresentar alomorfia. Afixos acrescentam informação: prefixos vêm antes da base e sufixos depois. Desinências expressam flexões nominais ou verbais. Vogal temática integra o tema verbal e indica a conjugação; tema é a combinação de radical e vogal temática.\n\nNem toda sequência que parece separável é morfema produtivo na palavra atual. Vogais e consoantes de ligação podem facilitar a pronúncia sem acrescentar significado lexical ou gramatical. A análise varia conforme o nível da gramática e a história da forma; use exemplos claros e critérios morfológicos.` },
      { heading: '2. Derivação', body: `Derivação prefixal acrescenta prefixo (“refazer”); sufixal acrescenta sufixo (“felizmente”); prefixal e sufixal ocorre quando prefixo e sufixo se acrescentam em etapas independentes (“infeliz” e “felizmente” existem); parassintética combina prefixo e sufixo simultaneamente, e a retirada de qualquer um impede a forma derivada pretendida (“entardecer”: não se formam “entarde” ou “tardecer” com o mesmo processo).\n\nDerivação regressiva forma com frequência substantivos a partir de verbos, por redução formal (“ataque” de atacar, em análise escolar); derivação imprópria muda a classe sem alterar a forma (“o jantar”, substantivo, em contraste com “jantar”, verbo). A classificação de alguns exemplos pode variar conforme a tradição gramatical e a análise sincrônica adotada.` },
      { heading: '3. Composição e outros processos', body: `Composição por justaposição combina bases sem perda fonológica relevante (“couve-flor”, “passatempo”); por aglutinação ocorre alteração ou perda de segmento (“planalto”, de plano + alto; “aguardente”, de água + ardente). Observe a forma resultante e as bases reconhecidas.\n\nOnomatopeias representam sons (“tique-taque”); abreviação vocabular reduz uma palavra (“foto”); siglas formam unidades com letras iniciais ou partes de expressões (IBGE); empréstimos incorporam formas de outras línguas; neologismos criam ou atribuem novos sentidos. Essas categorias podem ser analisadas por perspectivas diferentes, e uma palavra pode combinar processos.` },
      { heading: '4. Parassíntese: teste das formas intermediárias', body: `O teste escolar consiste em retirar prefixo ou sufixo e verificar se a forma restante existe com o significado e processo pertinentes. Em “envelhecer”, a análise tradicional identifica simultaneamente en- e -ecer; “velhecer” e “envelho” não funcionam como etapas derivacionais equivalentes. Em “infelizmente”, porém, “infeliz” e “felizmente” existem, portanto a formação não é parassintética: prefixo e sufixo podem ser acrescentados independentemente.\n\nNão basta que uma sequência seja inexistente em qualquer dicionário ou contexto; é preciso verificar se a forma intermediária é possível no sentido relevante. O teste é um instrumento didático para distinguir os processos, não uma prova etimológica universal.` },
      { heading: '5. Exemplo passo a passo', body: `Em “deslealdade”, reconheça a base “leal”, o prefixo des- e o sufixo -dade. Como “lealdade” e “desleal” existem, a derivação prefixal e sufixal é feita em etapas. Em “planalto”, a junção de plano + alto sofreu redução sonora: composição por aglutinação.\n\nEm prova, destaque os elementos, indique a transformação e justifique a classificação. Evite decidir apenas pelo número de pedaços visíveis ou pela grafia com hífen.` },
    ],
    example: '“Infelizmente”: feliz → infeliz (prefixação) e feliz → felizmente (sufixação); como as duas formas intermediárias existem, não é parassíntese. “Envelhecer” é tratado tradicionalmente como parassintético porque prefixo e sufixo formam juntos o verbo.',
    references: [],
    quickQuestions: [q('portugues-9-q1', '“Infelizmente” é parassintética porque apresenta prefixo e sufixo ao mesmo tempo na palavra final.', 'errado', 'A presença simultânea na forma final não basta: “infeliz” e “felizmente” existem, permitindo etapas independentes.')],
  },
  'portugues-10': {
    summary: 'Sinonímia aproxima significados; antonímia estabelece oposição. Essas relações são normalmente graduais e dependentes do contexto: palavras próximas não são necessariamente intercambiáveis em toda frase, e o antônimo adequado depende do sentido ativado.',
    lessonSections: [
      { heading: '1. Sinonímia e contexto', body: `Sinônimos compartilham parte do significado, mas costumam diferir em intensidade, registro, avaliação, colocação ou usos sintáticos. “Casa”, “lar”, “moradia” e “residência” podem se aproximar, mas não produzem o mesmo tom em todos os contextos. Sinônimos perfeitos, intercambiáveis em qualquer situação, são raros.\n\nPara testar uma substituição, mantenha a frase e confira sentido, gramática, registro e relações com o restante do texto. Uma palavra pode ser sinônima em uma acepção e não em outra: “velho amigo” frequentemente significa antigo amigo, não necessariamente idoso.` },
      { heading: '2. Antonímia e tipos de oposição', body: `Antônimos expressam sentidos opostos, mas a relação pode ser de escala, complementaridade ou reciprocidade. Quente/frio são graduais: há morno, gelado e outras posições. Vivo/morto são frequentemente tratados como complementares em determinado domínio, embora contextos figurados ou biológicos possam complicar a oposição. Comprar/vender são recíprocos: descrevem lados diferentes de uma transação.\n\nNem toda oposição é absoluta. “Rico” pode se opor a “pobre” em patrimônio, mas em “rica experiência” seu contraste seria “pouco expressiva” ou “limitada”, conforme o contexto. Identifique primeiro a acepção da palavra.` },
      { heading: '3. Relações semânticas próximas', body: `Homônimos têm formas iguais e significados distintos; parônimos têm formas parecidas, mas sentidos diferentes (“comprimento” e “cumprimento”). Hiperônimo designa uma classe mais ampla (“veículo”); hipônimo, um membro específico (“ônibus”). Essas relações ajudam a interpretar vocabulário e substituições.\n\nA banca pode pedir substituição de palavra sem alterar o sentido, sentido contextual, oposição ou valor de um conectivo. Não escolha pelo primeiro sinônimo de dicionário: use a frase e o argumento em que a palavra aparece.` },
      { heading: '4. Estratégia e exemplo', body: `Em “O texto é lacônico”, “sucinto” e “conciso” são substitutos plausíveis. Em “o autor foi lacônico em sua resposta”, a substituição também deve preservar a avaliação de brevidade. Em “uma política lacônica”, talvez o uso seja estranho porque a palavra pede outro tipo de referente.\n\nLeia a frase completa, determine a acepção, teste o substituto e confira se a conclusão do texto permanece. Quando a questão usa “sinônimo perfeito”, desconfie de termos próximos com diferenças de registro ou intensidade.` },
    ],
    example: '“Ele é um velho amigo” normalmente significa que a amizade é antiga; “ele é um idoso amigo” muda a interpretação. A proximidade entre palavras precisa ser avaliada dentro da acepção da frase.',
    references: [],
    quickQuestions: [q('portugues-10-q1', 'Palavras apontadas como sinônimas podem ser substituídas em qualquer contexto sem alterar o sentido ou o registro.', 'errado', 'A sinonímia costuma ser parcial; contexto, acepção, colocação e registro limitam a substituição.')],
  },
  'portugues-11': {
    summary: 'Pontuação organiza relações sintáticas, articula segmentos do texto e orienta a leitura. A escolha do sinal depende da estrutura e do efeito pretendido; a vírgula não deve separar termos que mantêm relação sintática direta, como sujeito e verbo ou verbo e complemento.',
    lessonSections: [
      { heading: '1. Pontuação e estrutura', body: `Ponto final encerra período declarativo; ponto de interrogação marca pergunta direta; exclamação registra entonação ou força expressiva. Dois-pontos introduzem explicação, enumeração, consequência, fala ou citação. Ponto e vírgula separa segmentos relacionados com autonomia maior do que a vírgula, e também organiza itens complexos.\n\nTravessão pode marcar fala, intercalação ou destaque; aspas marcam citação, uso metalinguístico ou distanciamento, conforme o contexto; parênteses inserem comentário ou informação acessória; reticências sugerem suspensão, omissão ou continuidade. Um sinal pode produzir mais de um efeito: explique o papel naquele trecho.` },
      { heading: '2. Usos frequentes da vírgula', body: `Use vírgula para separar itens de enumeração; isolar vocativo (“João, venha”); isolar aposto explicativo; marcar adjunto adverbial deslocado quando necessário ou para organizar a leitura; separar oração subordinada adverbial deslocada; isolar oração adjetiva explicativa; separar orações coordenadas em contextos apropriados; e indicar termo elíptico recuperável.\n\nOração adjetiva explicativa costuma vir entre vírgulas e acrescenta comentário; restritiva delimita o referente e não fica isolada por vírgulas. A pontuação pode alterar o sentido: “os servidores que estudaram passaram” restringe; “os servidores, que estudaram, passaram” apresenta a informação como explicativa sobre todos os servidores referidos.` },
      { heading: '3. Vírgulas proibidas por ruptura sintática', body: `Em ordem direta, não se separa sujeito de verbo, verbo de objeto ou nome de complemento por vírgula: “O professor explicou a matéria”; “A equipe entregou o relatório”; “A necessidade de recursos aumentou”. Pausas de leitura não justificam a vírgula.\n\nPode haver vírgula entre esses elementos quando uma intercalação real é isolada por duas vírgulas: “O professor, após a reunião, explicou a matéria”. Retire mentalmente o trecho intercalado: “O professor explicou a matéria”. Não deixe a vírgula de abertura sem a correspondente de fechamento.` },
      { heading: '4. Coordenação, conectivos e ambiguidade', body: `Antes de “mas”, “porém”, “contudo” e conectivos adversativos similares, costuma haver vírgula. Com “e”, a vírgula não é simplesmente proibida: pode ocorrer para separar orações com sujeitos diferentes, marcar intercalação, evitar ambiguidade, enfatizar uma pausa ou em enumerações complexas. A decisão depende da estrutura e do padrão editorial.\n\nOrações subordinadas adverbiais antepostas são geralmente separadas por vírgula: “Se estudar, avançará”. Quando pospostas, a vírgula pode ser usada conforme extensão, clareza e ênfase. Não transforme tendência em regra absoluta sem considerar o contexto sintático.` },
      { heading: '5. Exemplo comentado', body: `“Os candidatos deverão trazer documento oficial, caneta preta e água.” A enumeração simples usa vírgulas. Se cada item já contiver vírgulas internas, o ponto e vírgula pode separar os elementos maiores.\n\n“Os candidatos, que apresentaram recurso, aguardam resposta” (oração explicativa) tem leitura diferente de “Os candidatos que apresentaram recurso aguardam resposta” (apenas o subconjunto que recorreu). Em questões de reescrita, verifique se pontuação preserva referência, escopo e relação entre orações.` },
    ],
    example: 'Compare “Os servidores que concluíram o curso receberão certificado” (somente os que concluíram) com “Os servidores, que concluíram o curso, receberão certificado” (a oração entre vírgulas acrescenta explicação sobre o grupo referido).',
    references: [],
    quickQuestions: [q('portugues-11-q1', 'Uma pausa percebida na leitura é suficiente para justificar vírgula entre sujeito e verbo.', 'errado', 'A pontuação deve respeitar a estrutura sintática; não se separa sujeito e verbo por simples pausa.')],
  },
  'portugues-12': {
    summary: 'Pronomes substituem, acompanham ou retomam nomes e participantes do discurso. A classificação e a função dependem do contexto; em prova, observe referência, colocação, regência, concordância e a relação entre o pronome e o termo retomado.',
    lessonSections: [
      { heading: '1. Pronomes pessoais e funções', body: `Pronomes retos costumam exercer função de sujeito: eu, tu, ele/ela, nós, vós, eles/elas. Oblíquos átonos incluem me, te, se, o/a, lhe, nos, vos, os/as, lhes; tônicos aparecem geralmente com preposição: mim, ti, si, ele/ela, nós, vós, eles/elas. O uso depende da regência e da função, não apenas da pessoa referida.\n\nEm “Vi o menino” → “Vi-o”, o pronome o substitui objeto direto. Em “Entreguei o livro ao professor” → “Entreguei-lhe o livro”, lhe representa o destinatário. “Entre mim e você” usa pronome tônico; “para eu fazer” usa eu como sujeito do infinitivo. Não se deve dizer “para mim fazer” na norma-padrão quando mim seria sujeito do verbo fazer.` },
      { heading: '2. Pronomes de tratamento e demonstrativos', body: `Pronomes de tratamento exigem concordância verbal na terceira pessoa: “Vossa Excelência decidiu”. Adjetivos e particípios podem concordar com o referente, conforme a construção: “Vossa Excelência está satisfeita/satisfeito”, observando quem é o destinatário e o padrão institucional adotado. Formas cerimoniosas variam de uso e contexto.\n\nEste/esta/isto podem apontar para o que será apresentado ou para proximidade do enunciador; esse/essa/isso frequentemente retomam algo já mencionado ou se associam ao interlocutor; aquele/aquela/aquilo pode marcar distância. Essas são tendências didáticas, não uma regra rígida em todo português contemporâneo. Em enumeração de dois elementos, “este” pode retomar o mais próximo e “aquele” o mais distante.` },
      { heading: '3. Possessivos, indefinidos e interrogativos', body: `Possessivos indicam relação com as pessoas do discurso: meu, teu, seu, nosso, vosso e flexões. “Seu/sua” pode ser ambíguo entre diferentes possuidores; “dele/dela/deles/delas” pode esclarecer.\n\nIndefinidos expressam quantidade ou identidade imprecisa (“algum”, “ninguém”, “vários”, “tudo”). Interrogativos introduzem perguntas diretas ou indiretas (“quem”, “que”, “qual”, “quanto”). A classificação pode depender da função: “quanto” pode ser pronome, adjetivo ou advérbio conforme acompanha um nome ou modifica outra expressão.` },
      { heading: '4. Relativos e retomada', body: `Pronomes relativos retomam um antecedente e conectam uma oração adjetiva: “O livro que comprei chegou”. “Quem” costuma referir-se a pessoa e aparece frequentemente preposicionado: “a pessoa a quem me referi”. “O qual/a qual” pode evitar ambiguidade ou vir após preposição.\n\n“Cujo” estabelece relação de posse e concorda com o nome possuído (“o autor cujas obras li”); normalmente não admite artigo imediatamente depois: “cujo livro”, não “cujo o livro”. “Onde” retoma lugar; “aonde” combina a preposição a com onde em verbos que indicam movimento e regem a: “aonde você vai?”. Para origem, usa-se “de onde”.` },
      { heading: '5. Colocação pronominal e estratégia', body: `Pronomes átonos podem aparecer antes do verbo (próclise), depois (ênclise) ou entre formas verbais (mesóclise, em registros formais restritos). Palavras negativas, certos pronomes relativos e subordinativas frequentemente atraem próclise: “não me disseram”; “a pessoa que me chamou”. A colocação também depende da norma, do registro e da estrutura da oração.\n\nAo resolver, determine primeiro a que termo o pronome se refere, qual função exerce e qual preposição o verbo exige. Depois examine colocação e concordância. Em questão de substituição, confira se o referente, a regência e o sentido permanecem iguais.` },
    ],
    example: '“A diretora entregou o relatório aos analistas” pode ser reescrito como “A diretora entregou-lhes o relatório”: lhes substitui “aos analistas”, complemento indireto. Já “A diretora revisou o relatório” → “A diretora revisou-o”: o substitui objeto direto.',
    references: [],
    quickQuestions: [q('portugues-12-q1', 'Em “cujo relatório”, o relativo cujo concorda com o possuidor e pode ser seguido pelo artigo “o”.', 'errado', '“Cujo” concorda com o nome possuído (“relatório”) e, na construção padrão, não é seguido diretamente de artigo.')],
  },
  'portugues-13': {
    summary: 'Concordância nominal ajusta determinantes, quantificadores e adjetivos ao substantivo; concordância verbal relaciona o verbo ao sujeito. Há regras gerais e casos especiais, e algumas construções admitem mais de uma concordância conforme estrutura, posição e sentido.',
    lessonSections: [
      { heading: '1. Concordância nominal: regra e posição', body: `Artigos, pronomes adjetivos, numerais e adjetivos concordam normalmente em gênero e número com o substantivo: “as novas propostas”; “dois relatórios completos”. Quando um adjetivo se refere a mais de um substantivo, a concordância depende da posição, do gênero e do sentido.\n\nAdjetivo posposto a substantivos de gêneros diferentes pode ir ao masculino plural (“camisa e sapato novos”) ou concordar com o mais próximo em certas construções (“camisa e sapato novo”), especialmente quando a relação semântica favorece essa leitura. Anteposto, geralmente concorda com o substantivo mais próximo: “escolheu boa hora e lugar”, embora a interpretação possa orientar outras construções. Analise a frase e a norma cobrada.` },
      { heading: '2. Expressões e palavras variáveis', body: `“É proibido”, “é necessário”, “é bom” e expressões semelhantes tendem a ficar invariáveis quando o substantivo vem sem determinante: “É proibido entrada” (uso corrente) / “É proibida a entrada”. Com artigo ou determinante, a concordância feminina é marcada.\n\n“Menos” é invariável. “Meio” é invariável como advérbio (“meio cansada”) e varia como numeral/adjetivo com sentido de metade (“meia hora”). “Bastante” varia quando equivale a muitos/as (“bastantes razões”) e tende a ser invariável como advérbio (“estudou bastante”). “Anexo”, “incluso”, “mesmo”, “próprio” e “obrigado” variam quando funcionam como adjetivos ou formas concordantes; expressões como “em anexo” permanecem invariáveis.` },
      { heading: '3. Concordância verbal com sujeito simples e composto', body: `O verbo concorda em pessoa e número com o núcleo do sujeito, não necessariamente com o termo mais próximo. Sujeito composto antes do verbo normalmente leva o plural: “João e Maria chegaram”. Com sujeito composto posposto, podem ocorrer plural ou concordância com o núcleo mais próximo em certos contextos: “Chegaram João e Maria” / “Chegou João e Maria”.\n\nCom expressões partitivas (“a maioria de”, “grande parte de”), pode haver concordância com o núcleo singular ou com o complemento plural, conforme foco e norma: “A maioria dos candidatos aprovou/aprovaram”. Em prova, observe se a questão permite ambas ou fixa uma forma pelo padrão solicitado.` },
      { heading: '4. Casos especiais de concordância verbal', body: `“Mais de um” costuma levar verbo ao singular (“Mais de um candidato faltou”), mas a reciprocidade pode levar ao plural (“Mais de um candidato se cumprimentaram”). “Um ou outro” tende ao singular; construções com “nem... nem” podem variar conforme a estrutura e o sentido. O verbo ser pode concordar com sujeito ou predicativo em construções específicas (“Tudo são flores”; “A vida são alegrias”), mas há padrões particulares com datas, horas, medidas e expressões identificadoras.\n\nVerbos impessoais permanecem na terceira pessoa do singular: haver com sentido de existir (“Havia documentos”), fazer indicando tempo decorrido (“Faz cinco anos”) e fenômenos meteorológicos sem sujeito (“Choveu”). Não confunda “haver” existencial com “existir”: “Existiam documentos” concorda com o sujeito plural.` },
      { heading: '5. Partícula SE e sujeito oracional', body: `Com “se” apassivador, verbo transitivo direto (ou direto e indireto, conforme a construção) forma passiva sintética e concorda com o sujeito paciente: “Vendem-se casas” = casas são vendidas. Com índice de indeterminação do sujeito, o verbo fica na terceira pessoa do singular: “Precisa-se de funcionários” (precisar de rege preposição).\n\nUma oração inteira pode exercer função de sujeito: “É necessário que os candidatos estudem”; “Falta revisar o conteúdo”. Nesse caso, a oração principal fica geralmente na terceira pessoa do singular. Para decidir com “se”, procure se o verbo admite objeto direto e se o sintagma nominal pode ser sujeito paciente; não use apenas a presença de um plural para escolher a forma.` },
    ],
    example: '“Havia muitas pessoas na sala” permanece no singular porque haver significa existir e é impessoal. “Existiam muitas pessoas na sala” concorda com o sujeito “muitas pessoas”. O significado é próximo, mas a concordância muda com o verbo empregado.',
    references: [],
    quickQuestions: [q('portugues-13-q1', 'Em “Havia muitos documentos”, o verbo haver fica no plural para concordar com “documentos”.', 'errado', 'Haver com sentido de existir é impessoal e permanece na terceira pessoa do singular: havia documentos.')],
  },
  'portugues-14': {
    summary: 'Flexão nominal varia substantivos, adjetivos e determinantes em gênero, número e grau; flexão verbal marca pessoa, número, modo, tempo e, em certas análises, aspecto. A forma correta depende da classe, do paradigma e do contexto sintático.',
    lessonSections: [
      { heading: '1. Gênero e número dos nomes', body: `Há substantivos biformes, com formas distintas para masculino e feminino (“menino/menina”); comuns de dois gêneros, cuja distinção se faz pelo determinante (“o/a estudante”); sobrecomuns, com gênero gramatical único para pessoas de ambos os sexos (“a criança”, “o cônjuge”); e epicenos, usados para animais com um gênero gramatical (“a cobra macho/a cobra fêmea”). As classificações podem variar em detalhes conforme a gramática.\n\nO plural se forma frequentemente com -s, mas terminações exigem atenção: palavras em -m geralmente passam a -ns (“homem/homens”); em -r e -z, acrescenta-se -es (“mar/mares”, “vez/vezes”); em -ão, há plurais em -ões, -ães e -ãos, que muitas vezes precisam ser memorizados (“leões”, “pães”, “mãos”). Palavras terminadas em -al/-el/-ol/-ul costumam mudar o final para -ais/-éis/-óis/-uis, com exceções lexicais.` },
      { heading: '2. Grau nominal', body: `O grau pode ser expresso por sufixos aumentativos e diminutivos (“casarão”, “casinha”) ou por palavras independentes (“casa muito grande”, “casa pequena”). A forma diminutiva pode indicar tamanho, afeto, ironia ou desprezo; o efeito depende do contexto.\n\nNão confunda grau com flexão de gênero ou número. Em análise escolar, aumentativo e diminutivo são tratados como flexão de grau em algumas abordagens e como derivação em outras; siga a terminologia da questão e reconheça o efeito semântico.` },
      { heading: '3. Estrutura e flexão verbal', body: `Uma forma verbal pode ser analisada em radical, vogal temática e desinências. As desinências modo-temporais e número-pessoais indicam informações como tempo, modo, pessoa e número. Os modos principais são indicativo, subjuntivo e imperativo; tempos situam a ação em relação ao marco temporal do enunciado.\n\nOs verbos regulares seguem paradigmas previsíveis; irregulares alteram o radical ou as terminações; defectivos não apresentam todas as formas em certas descrições; abundantes podem ter mais de um particípio ou forma. O infinitivo, o gerúndio e o particípio são formas nominais e não marcam pessoa do mesmo modo que as formas finitas.` },
      { heading: '4. Tempos e modos: valores no contexto', body: `No indicativo, presente pode expressar atualidade, hábito, verdade geral ou presente histórico; pretérito perfeito costuma apresentar fato concluído; imperfeito pode indicar duração, hábito ou pano de fundo; mais-que-perfeito marca anterioridade em relação a outro passado; futuros indicam posterioridade, hipótese, ordem ou probabilidade, conforme o contexto.\n\nO subjuntivo aparece frequentemente em contextos de dúvida, desejo, hipótese, finalidade e condição, mas não é simplesmente “modo da dúvida”. O imperativo expressa ordem, pedido, conselho ou instrução; suas formas relacionam-se a pessoas de tratamento e ao subjuntivo. Verifique os paradigmas corretos: futuro do presente de partir é “partirei”, não “parterei”.` },
      { heading: '5. Aplicação em prova', body: `Uma questão pode pedir tempo, modo, pessoa, número, conjugação, forma nominal ou mudança de sentido causada pela flexão. Localize o verbo, identifique a terminação, encontre o sujeito quando houver concordância e interprete a relação temporal no período.\n\nCompare “Quando chegar, avisarei” (futuro do subjuntivo após quando com referência futura) e “Quando chegava, avisava” (hábito no passado). A terminação verbal não deve ser classificada fora da frase, pois formas homônimas podem pertencer a tempos ou pessoas diferentes.` },
    ],
    example: '“As candidatas estavam meio cansadas”: meio é advérbio, invariável. “As candidatas estudaram meia hora”: meia é numeral/adjetivo que concorda com hora. A função e o sentido definem a flexão.',
    references: [],
    quickQuestions: [q('portugues-14-q1', 'Em “As alunas estavam meio cansadas”, a forma “meio” varia para concordar com o feminino plural.', 'errado', '“Meio” significa “um pouco” e funciona como advérbio; por isso fica invariável.')],
  },
  'portugues-15': {
    summary: 'Voz verbal apresenta a relação entre sujeito e processo: na ativa, o sujeito é apresentado como agente ou participante; na passiva, como paciente; na reflexiva, o sujeito participa como agente e paciente ou estabelece relação recíproca. A transformação entre vozes depende da transitividade e da preservação do sentido.',
    lessonSections: [
      { heading: '1. Voz ativa', body: `Na voz ativa, o sujeito é apresentado como agente ou como participante que desencadeia o processo: “A equipe revisou o relatório”. O sujeito é “a equipe”; “o relatório” é objeto direto. Nem todo sujeito ativo é um agente voluntário — em “A tempestade destruiu o telhado”, o sujeito é causa do evento.\n\nA voz descreve a perspectiva gramatical, não necessariamente intenção ou responsabilidade. Identifique sujeito, verbo e complementos antes de classificar.` },
      { heading: '2. Voz passiva analítica', body: `A passiva analítica é formada tipicamente por verbo auxiliar ser + particípio: “O relatório foi revisado pela equipe”. O objeto direto da ativa passa a sujeito paciente; o sujeito da ativa pode ser indicado como agente da passiva com “por” ou “de”, mas pode ser omitido. O particípio concorda em gênero e número com o sujeito paciente.\n\nO tempo e o modo são mantidos no auxiliar: “A equipe revisará o relatório” → “O relatório será revisado pela equipe”. Não basta encontrar “ser + particípio”: confira se a estrutura realmente permite leitura passiva e se o particípio pertence ao verbo principal.` },
      { heading: '3. Voz passiva sintética e valores de SE', body: `A passiva sintética ou pronominal costuma ocorrer com verbo transitivo direto e pronome apassivador se: “Vendem-se casas” equivale a “Casas são vendidas”. O sujeito paciente (“casas”) controla a concordância verbal.\n\nCompare com índice de indeterminação do sujeito: “Precisa-se de analistas”. O verbo rege preposição de, não há objeto direto que se transforme em sujeito paciente; o sujeito fica indeterminado e o verbo permanece no singular. Há usos e análises que exigem cuidado, mas a transitividade é o principal diagnóstico escolar.` },
      { heading: '4. Voz reflexiva e recíproca', body: `Na reflexiva, o sujeito pratica e recebe a ação ou é afetado por ela: “A candidata se preparou”; “O menino se cortou”. O pronome pode ter valor reflexivo, mas construções pronominais também podem expressar mudança de estado ou outros valores, sem equivaler a uma passiva.\n\nNa recíproca, dois ou mais participantes realizam a ação uns sobre os outros: “Os colegas se cumprimentaram”. Acrescentar “um ao outro” ajuda a testar a leitura recíproca. O contexto distingue reflexividade individual, reciprocidade e usos pronominais lexicalizados.` },
      { heading: '5. Transformação e limites', body: `Transformação ativa → passiva: (1) confirme objeto direto; (2) transforme-o em sujeito paciente; (3) passe o verbo para ser + particípio, preservando tempo e modo; (4) ajuste concordância; (5) acrescente o agente se necessário. “A comissão publicou as regras” → “As regras foram publicadas pela comissão”.\n\nVerbos intransitivos, de ligação e transitivos indiretos não formam normalmente passiva analítica com objeto indireto como sujeito na análise tradicional. Ao avaliar uma reescrita, preserve tempo, modalidade, negação, agente e sentido; nem toda frase com se deve ser convertida em passiva.` },
    ],
    example: 'Ativa: “A banca anulou as questões.” Passiva analítica: “As questões foram anuladas pela banca.” Passiva sintética: “Anularam-se as questões.” Em ambas as passivas, “as questões” é sujeito paciente plural, e o verbo concorda no plural.',
    references: [],
    quickQuestions: [q('portugues-15-q1', 'Em “Vendem-se casas”, “casas” é sujeito paciente e o verbo concorda com esse termo.', 'certo', 'A construção é passiva sintética: casas são vendidas. O sujeito paciente plural exige verbo no plural.')],
  },
  'portugues-16': {
    summary: 'Correlação verbal organiza os tempos e modos para expressar anterioridade, simultaneidade, posterioridade, condição, hipótese e finalidade. A relação entre as formas depende do sentido e do marco temporal, não de uma tabela única que se aplique a todo período.',
    lessonSections: [
      { heading: '1. Tempo verbal e marco de referência', body: `Um tempo verbal situa o processo em relação ao momento da fala ou a outro marco temporal. Pretérito mais-que-perfeito, por exemplo, pode marcar fato anterior a outro fato passado: “Quando cheguei, a sessão já começara/tinha começado”. Presente pode enunciar hábito, verdade geral ou fato atual.\n\nAo analisar correlação, identifique primeiro os acontecimentos e a ordem entre eles; depois observe modo, aspecto e conectivos. Duas formas diferentes podem ser adequadas se exprimirem relações diferentes. A questão de concurso costuma avaliar se a combinação preserva coerência temporal e modal.` },
      { heading: '2. Subjuntivo em orações dependentes', body: `Verbos de dúvida, desejo, necessidade, possibilidade e avaliação frequentemente introduzem oração com subjuntivo: “Duvido que ele venha”; “É possível que tenham chegado”. O tempo escolhido depende do marco e da relação temporal: “Duvidei que ele viesse” ou “Duvidei que tivesse vindo” expressam relações diferentes.\n\nNão é correto dizer que fato anterior ao verbo principal presente exige sempre pretérito imperfeito do subjuntivo. A forma composta “tenha vindo” pode marcar anterioridade relacionada ao presente (“Duvido que ele tenha vindo”). Considere a variedade padrão e a nuance temporal que o enunciado quer expressar.` },
      { heading: '3. Condicionais com SE', body: `Condição possível ou aberta no futuro frequentemente usa futuro do subjuntivo na oração introduzida por se e futuro do presente ou imperativo na principal: “Se puder, irei”; “Se receber o documento, avise-me”. Condição hipotética ou pouco provável costuma combinar pretérito imperfeito do subjuntivo e futuro do pretérito: “Se pudesse, iria”.\n\nHipótese não realizada no passado pode usar mais-que-perfeito composto do subjuntivo e futuro do pretérito composto: “Se tivesse podido, teria ido”. Essas estruturas são modelos frequentes, mas o sentido e o contexto governam a escolha. Na norma-padrão, evite “se eu estudaria” em oração condicional que pede subjuntivo; use “se eu estudasse”.` },
      { heading: '4. Orações temporais e conectivos', body: `Com referência futura, “quando”, “assim que”, “logo que” e expressões semelhantes costumam vir com futuro do subjuntivo: “Quando chegar, avisarei”; “Assim que concluir, enviarei”. Para hábito ou situação passada, pode ocorrer indicativo ou subjuntivo conforme o sentido: “Quando chegava, avisava”; “Quando chegasse, avisaria”.\n\nO futuro do subjuntivo de verbos regulares muitas vezes coincide com o infinitivo (“quando estudar”), mas em irregulares há formas próprias (“quando fizer”, “quando vier”, “quando puder”). Não confunda “quando você chegar” com “quando você chegará”: na oração temporal futura, a forma padrão é subjuntivo; a oração principal pode marcar o futuro com indicativo.` },
      { heading: '5. Reescrita e resolução de questões', body: `Em questões de substituição, compare o período inteiro antes e depois. Verifique se a relação de causa, condição, concessão, finalidade ou tempo permaneceu; se o acontecimento continua futuro, passado ou hipotético; e se o modo verbal é exigido pelo conectivo e pela intenção.\n\n“Se estudasse, passaria” expressa hipótese; “Se estudar, passará” apresenta condição futura possível. “Quando chegar, avisarei” expressa posterioridade; “Quando chegasse, avisaria” situa a ação em quadro hipotético ou passado. Formas diferentes não são automaticamente erradas: a interpretação pretendida é o critério.` },
    ],
    example: 'Compare “Se puder, irei” (condição possível) e “Se pudesse, iria” (hipótese). A troca de tempos e modos altera o grau de possibilidade, não é apenas uma mudança formal.',
    references: [],
    quickQuestions: [q('portugues-16-q1', 'Na norma-padrão, uma condição futura introduzida por “se” costuma usar o futuro do subjuntivo: “Se puder, irei”.', 'certo', 'A combinação é frequente para condição futura possível; outras correlações dependem do sentido e do contexto.')],
  },
};
